// @Embeddable VALUE object — NO @Id, no lifecycle, owned by its account
package com.bank.profile.model;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.util.Objects;

@Embeddable
public class Nominee {

    private String name;
    private String relationship;

    @Column(name = "share_percent")
    private int sharePercent;

    protected Nominee() {}

    public Nominee(String name, String relationship, int sharePercent) {
        this.name = name;
        this.relationship = relationship;
        this.sharePercent = sharePercent;
    }

    public String getName() { return name; }
    public String getRelationship() { return relationship; }
    public int getSharePercent() { return sharePercent; }

    // value equality — two nominees with the same data are the same value
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Nominee n)) return false;
        return sharePercent == n.sharePercent
            && Objects.equals(name, n.name)
            && Objects.equals(relationship, n.relationship);
    }
    @Override public int hashCode() { return Objects.hash(name, relationship, sharePercent); }
}
