package com.bank.profile.model;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @Column(name = "account_id")
    private String accountId;

    @Column(name = "holder_name", nullable = false)
    private String holderName;

    // @ElementCollection of BASIC type → value table, cascaded with the account
    @ElementCollection
    @CollectionTable(name = "account_phones", joinColumns = @JoinColumn(name = "account_id"))
    @Column(name = "phone")
    private List<String> phoneNumbers = new ArrayList<>();

    // @ElementCollection of EMBEDDABLE value objects, @OrderColumn avoids delete-all-reinsert
    @ElementCollection
    @CollectionTable(name = "account_nominees", joinColumns = @JoinColumn(name = "account_id"))
    @OrderColumn(name = "position")
    private List<Nominee> nominees = new ArrayList<>();

    // @OneToMany to an ENTITY (trades have their own identity) — mapped by accountId column
    @OneToMany(fetch = FetchType.LAZY)
    @JoinColumn(name = "account_id")
    private List<Trade> trades = new ArrayList<>();

    protected Account() {}

    public void addPhone(String phone) { phoneNumbers.add(phone); }
    public void addNominee(Nominee nominee) { nominees.add(nominee); }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public List<String> getPhoneNumbers() { return phoneNumbers; }
    public List<Nominee> getNominees() { return nominees; }
    public List<Trade> getTrades() { return trades; }
}
