            a.getAccountId(), a.getHolderName(),
            List.copyOf(a.getPhoneNumbers()),
            a.getNominees().stream()
                .map(n -> new NomineeLine(n.getName(), n.getRelationship(), n.getSharePercent()))
                .toList(),
            a.getTrades().size());
