package com.bank.profile.service;

import com.bank.profile.dto.ProfileView;
import com.bank.profile.model.Account;
import com.bank.profile.model.Nominee;
import com.bank.profile.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountService {

    private final AccountRepository accountRepo;

    // Add a basic-type value — cascaded as part of the account on flush
    @Transactional
    public ProfileView addPhone(String accountId, String phone) {
        Account account = accountRepo.findById(accountId).orElseThrow();
        account.addPhone(phone);
        // No separate save of the phone — it is a value owned by the account
        log.info("Added phone value to {} (account_phones table)", accountId);
        return ProfileView.from(account);
    }

    // Add an embeddable value object — @OrderColumn keeps updates targeted
    @Transactional
    public ProfileView addNominee(String accountId, String name, String rel, int share) {
        Account account = accountRepo.findById(accountId).orElseThrow();
        account.addNominee(new Nominee(name, rel, share));
        log.info("Added nominee VALUE object to {} (account_nominees, no independent id)", accountId);
        return ProfileView.from(account);
    }

    @Transactional(readOnly = true)
    public ProfileView view(String accountId) {
        return ProfileView.from(accountRepo.findById(accountId).orElseThrow());
    }
}
