package com.bank.profile.model;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import static org.assertj.core.api.Assertions.*;

class ValueVsEntityTest {

    @Test
    void nomineeHasNoIdField() {
        // A value object must NOT have an @Id — it has no independent identity
        boolean hasId = false;
        for (Field f : Nominee.class.getDeclaredFields()) {
            if (f.isAnnotationPresent(jakarta.persistence.Id.class)) hasId = true;
        }
        assertThat(hasId).isFalse();
    }

    @Test
    void nomineeUsesValueEquality() {
        Nominee a = new Nominee("Asha Kumar", "SPOUSE", 60);
        Nominee b = new Nominee("Asha Kumar", "SPOUSE", 60);
        // same data → equal values (value semantics, not identity)
        assertThat(a).isEqualTo(b);
        assertThat(a.hashCode()).isEqualTo(b.hashCode());
    }

    @Test
    void tradeIsAnEntityWithIdentity() {
        boolean hasId = false;
        for (Field f : Trade.class.getDeclaredFields()) {
            if (f.isAnnotationPresent(jakarta.persistence.Id.class)) hasId = true;
        }
        assertThat(hasId).isTrue(); // Trade has @Id → it is an entity
    }
}
